mapper.update:
UPDATE rental_overdue_fee SET reported_method=#{method},reported_at=#{handoverAt},reported_basis=#{basis},
    reported_by=#{actor},disputed=#{disputed},fee_status='pending_review',version=version+1,updated_at=#{now}
    WHERE rental_order_id=#{orderId} AND fee_status='awaiting_handover'

mapper.insert:
INSERT INTO order_compensation_receivable(id,receivable_no,rental_order_id,buyer_user_id,factory_id,source_type,source_id,
    confirmed_loss_amount_fen,available_deposit_amount_fen,deposit_deducted_amount_fen,receivable_amount_fen,paid_amount_fen,waived_amount_fen,
    receivable_status,effective_at,version,created_at,updated_at)
    SELECT #{id},CONCAT('RC',#{id}),o.id,o.buyer_user_id,o.factory_id,'overdue_return',f.id,f.liability_fen,#{available},f.liability_offset_fen,
      f.rent_fen-f.rent_offset_fen+f.liability_fen-f.liability_offset_fen,0,0,'pending',#{now},0,#{now},#{now}
    FROM rental_order o JOIN rental_overdue_fee f ON f.rental_order_id=o.id WHERE o.id=#{orderId}
